fields.InputDefinition:
{
  "goal": "Do the shared setup ONCE: open the 'Realtime Recordings' application via the application switcher dropdown next to the logo and wait for the recordings list to load. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) click-select-playback — if at least one recording row is present, CLICK it and wait for the right-hand playback pane to load; confirm the detail pane mounts an audio/media player (play controls / scrubber) together with a transcript view (or shows 'Loading recording...' then the player), replacing the 'Select a session to replay' prompt — if the list is empty, the 'No recorded sessions yet' empty state is a pass (you do NOT need to hear audio); (2) keyboard-select-row — if at least one recording row is present, use the KEYBOARD: press Tab to move focus onto a recording row (rows are keyboard-focusable list options), then press Enter (or Space) to activate it, and confirm the right pane responds by loading/showing playback (player, transcript, or a loading indicator) — do NOT use a mouse click for this activation step; if the list is empty, the empty state is a pass. Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "click-select-playback",
      "instruction": "click a recording loads the media player",
      "visualCriteria": [
        "Clicking a recording row loads the right playback pane with a media/audio player (play button or scrubber visible) and/or a transcript panel, replacing the 'Select a session to replay' prompt — OR a valid empty state if no recordings exist"
      ]
    },
    {
      "name": "keyboard-select-row",
      "instruction": "keyboard Enter/Space selects a recording",
      "visualCriteria": [
        "A recording row receives keyboard focus (via Tab) and pressing Enter or Space selects it so the right pane responds by loading/showing playback (player, transcript, or a loading indicator) — OR, if no recordings exist, a clear empty state is shown"
      ]
    }
  ]
}
